// @ts-nocheck — plain JS script; imported by issue-to-content.test.ts (no shebang, see import-survey.mjs).
/**
 * Keeps the "Tour" dropdown in the issue forms in step with content/routes/.
 *
 * GitHub issue-form dropdowns are static YAML, so the options can't be filled
 * at runtime. The templates carry a generated region:
 *
 *       options:
 *         # tours:begin (generated by scripts/sync-issue-templates.mjs)
 *         - cissbury-ring
 *         # tours:end
 *
 * Usage: node scripts/sync-issue-templates.mjs   (npm run content:sync-templates)
 */
import { readFileSync, writeFileSync, existsSync, readdirSync } from 'node:fs'
import { join } from 'node:path'
import { pathToFileURL } from 'node:url'
import { execFileSync } from 'node:child_process'

const BEGIN = /^([ \t]*)# tours:begin.*$/m
const END = /^[ \t]*# tours:end[ \t]*$/m

export const TEMPLATES_WITH_TOUR_DROPDOWN = ['add-stop.yml', 'edit-stop.yml']

/** True when git says `path` is ignored. Any other outcome (not ignored, not a
 * git checkout, git missing) is "not ignored" — the fallback is the plain listing. */
function isGitIgnored(path) {
  try {
    execFileSync('git', ['check-ignore', '-q', path], { stdio: 'ignore' })
    return true
  } catch {
    return false
  }
}

/** Tour folders under content/routes/, minus git-ignored ones (local
 * experiments). Untracked-but-not-ignored folders ARE listed: the issue
 * workflow syncs right after generating a new tour, before it is committed. */
export function listTourIds(contentRoot = 'content') {
  const dir = join(contentRoot, 'routes')
  if (!existsSync(dir)) return []
  return readdirSync(dir, { withFileTypes: true })
    .filter((d) => d.isDirectory() && existsSync(join(dir, d.name, 'tour.yaml')))
    .filter((d) => !isGitIgnored(join(dir, d.name)))
    .map((d) => d.name)
    .sort()
}

/** Pure: the template text with its generated region rewritten for `ids`. */
export function renderTemplate(text, ids) {
  const b = BEGIN.exec(text)
  const e = END.exec(text)
  if (!b || !e || e.index < b.index) throw new Error('template has no `# tours:begin` … `# tours:end` region')
  const indent = b[1]
  const head = text.slice(0, b.index + b[0].length)
  const tail = text.slice(e.index)
  const list = ids.map((id) => `${indent}- ${id}`).join('\n')
  return `${head}\n${list}\n${tail.startsWith(indent) ? tail : indent + tail.trimStart()}`
}

/** Rewrites the templates in place; returns the file names that changed. */
export function syncTemplates({ contentRoot = 'content', templatesDir = '.github/ISSUE_TEMPLATE' } = {}) {
  const ids = listTourIds(contentRoot)
  const changed = []
  for (const name of TEMPLATES_WITH_TOUR_DROPDOWN) {
    const p = join(templatesDir, name)
    const before = readFileSync(p, 'utf-8')
    const after = renderTemplate(before, ids)
    if (after !== before) {
      writeFileSync(p, after)
      changed.push(name)
    }
  }
  return changed
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) {
  const changed = syncTemplates()
  console.log(changed.length ? `Updated: ${changed.join(', ')}` : 'Issue templates already match content/routes/.')
}
